fn hermeline(off: f64, scl: f64) -> Vec<f64> {
    // If scl is zero (either +0.0 or -0.0), force it to be exactly +0.0.
    // Otherwise, preserve the value of scl.
    let second = if scl == 0.0 { 0.0 } else { scl };
    vec![off, second]
}

